// Content-bearing WP REST types (edit list to add/remove CPTs)
const types = ['pages','posts','campaign','causes','awards','alumni_story','news','csr','allstory','casestudy','events_list','annual_report','annual_contributors','legacy_project','batch_legacy','jobs','dean_desk','dean_circle','leadership_circle','giving_circle','chairman_circle','director_circle'];
const base = 'https://acr.iitbombay.org/wp-json/wp/v2/';
const TRAFILATURA_URL = 'http://acr-trafilatura:8000/extract'; // container name on n8n-net, internal port 8000
const since = ($json.value ? String($json.value) : '1970-01-01T00:00:00');
const out = [];
const MAX_ITEMS = 0; // >0 = TEST MODE: ingest only first N posts, watermark NOT advanced. 0 = full run.
let postCount = 0;
let maxMod = since;

// Header-aware sectioning: split markdown on #..###### headings, carry heading.
function sectionize(md) {
  const lines = String(md).split('\n');
  const secs = [];
  let cur = { heading: '', body: [] };
  for (const ln of lines) {
    const m = ln.match(/^(#{1,6})\s+(.*)$/);
    if (m) {
      if (cur.heading || cur.body.join('').trim()) secs.push(cur);
      cur = { heading: m[2].trim(), body: [] };
    } else { cur.body.push(ln); }
  }
  if (cur.heading || cur.body.join('').trim()) secs.push(cur);
  return secs.length ? secs : [{ heading: '', body: [String(md)] }];
}

for (const t of types) {
  let page = 1;
  while (true) {
    let items;
    try {
      items = await this.helpers.httpRequest({
        method: 'GET', url: base + t, json: true,
        qs: { status: 'publish', per_page: 100, page, modified_after: since, orderby: 'modified', order: 'asc', _fields: 'id,link,title,modified,status,content' }
      });
    } catch (e) { break; }
    if (!Array.isArray(items) || items.length === 0) break;
    for (const it of items) {
      if (it.id === 2) continue; // Sample Page
      // Convert WP content.rendered HTML -> Markdown via self-hosted Trafilatura service.
      const rawHtml = (it.content && it.content.rendered) ? it.content.rendered : '';
      let md = '';
      if (rawHtml) {
        try {
          const r = await this.helpers.httpRequest({ method: 'POST', url: TRAFILATURA_URL, json: true, body: { html: rawHtml } });
          md = (r && r.markdown) ? r.markdown : '';
        } catch (e) { md = ''; }
      }
      const title = (it.title && it.title.rendered) ? it.title.rendered : '';
      const secs = sectionize(md);
      const outline = secs.map(s => s.heading).filter(Boolean).join(' | ');
      let ci = 0;
      for (const s of secs) {
        const body = s.body.join('\n').trim();
        if (!body && !s.heading) continue;
        const heading = s.heading || title;
        // Base chunk text; the LLM contextual prefix (Phase 2) is prepended downstream.
        const content = (title + (s.heading ? ' \u2014 ' + s.heading : '') + '\n\n' + body).trim();
        out.push({ json: { post_id: it.id, source_type: t, url: it.link, title, modified: it.modified, section_heading: heading, chunk_index: ci, outline, content } });
        ci++;
      }
      if (it.modified && it.modified > maxMod) maxMod = it.modified;
      postCount++;
      if (MAX_ITEMS > 0 && postCount >= MAX_ITEMS) break;
    }
    if (MAX_ITEMS > 0 && postCount >= MAX_ITEMS) break;
    if (items.length < 100) break;
    page++;
  }
  if (MAX_ITEMS > 0 && postCount >= MAX_ITEMS) break;
}
const finalMax = (MAX_ITEMS > 0) ? since : maxMod; // test mode leaves watermark untouched
for (const o of out) o.json._maxModified = finalMax;
return out;

const src = $('Restore Items').all();
const ai = $input.all();
return src.map((s, i) => {
  let ctx = '';
  try { ctx = String(ai[i].json.choices[0].message.content).trim(); } catch (e) { ctx = ''; }
  const j = { ...s.json };
  j.context = ctx;
  j.content = ctx ? (ctx + '\n\n' + j.content) : j.content;
  return { json: j };
});
